"""Object storage for original uploads. Implementations: memory (tests), local (dev), gcs."""

from __future__ import annotations

import re
from typing import Protocol

_KEY = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/-]{0,500}$")


class ObjectNotFound(Exception):
    """No object under that key."""


def validate_key(key: str) -> str:
    """Keys are generated by us; refuse anything that could escape a prefix."""
    if not _KEY.fullmatch(key) or ".." in key.split("/") or "//" in key:
        raise ValueError(f"invalid storage key: {key!r}")
    return key


class Storage(Protocol):
    async def put(self, key: str, data: bytes, content_type: str) -> None: ...

    async def get(self, key: str) -> bytes: ...

    async def delete(self, key: str) -> None: ...
